CREATE TABLE IF NOT EXISTS mentors (id BIGSERIAL PRIMARY KEY, user_id BIGINT NOT NULL UNIQUE REFERENCES users(id) ON DELETE CASCADE, specialization VARCHAR(255), designation VARCHAR(255));
CREATE TABLE IF NOT EXISTS mentor_students (id BIGSERIAL PRIMARY KEY, mentor_id BIGINT NOT NULL REFERENCES mentors(id) ON DELETE CASCADE, student_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, assigned_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(mentor_id, student_id));
CREATE INDEX IF NOT EXISTS idx_mentor_students_mentor ON mentor_students(mentor_id);
CREATE TABLE IF NOT EXISTS mentor_feedback (id BIGSERIAL PRIMARY KEY, mentor_id BIGINT NOT NULL REFERENCES mentors(id) ON DELETE CASCADE, student_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, feedback_type VARCHAR(40) NOT NULL, feedback TEXT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS resume_feedback (id BIGSERIAL PRIMARY KEY, resume_id BIGINT NOT NULL REFERENCES resumes(id) ON DELETE CASCADE, mentor_id BIGINT NOT NULL REFERENCES mentors(id) ON DELETE CASCADE, feedback TEXT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
ALTER TABLE resumes ADD COLUMN IF NOT EXISTS review_status VARCHAR(20) NOT NULL DEFAULT 'PENDING';
